const baseUrl=document.currentScript.src.substring(0,document.currentScript.src.lastIndexOf("js/"));function loadScript(e){return new Promise((t,s)=>{const n=document.createElement("script");n.src=e;n.onload=t;n.onerror=s;document.head.appendChild(n)})}const loadedLinks=new Set;async function loadDependencyMap(e){try{const t=await fetch(e);if(!t.ok)throw new Error(`Ошибка загрузки JSON | Loading error JSON: ${t.statusText}`);const s=await t.json();return s}catch(e){console.error("Ошибка при загрузке или парсинге dependencyMap | Error loading or parsing dependencyMap:",e);return{desktop:{landscape:[{desktop:"landscape"}],portrait:[{desktop:"portrait"}]},tablet:{landscape:[{tablet:"landscape"}],portrait:[{tablet:"portrait"}]},mobile:{landscape:[{mobile:"landscape"}],portrait:[{mobile:"portrait"}]}}}}function loadLink(e,t=""){if(loadedLinks.has(e))console.log(`Пропуск: "${e}" уже загружен | Skip: "${e}" is already loaded.`);else{const s=document.createElement("link");s.id=t;s.href=e;s.rel="stylesheet";s.type="text/css";document.head.appendChild(s);loadedLinks.add(e)}}function areDependenciesEqual(e,t){return Object.keys(e)[0]===Object.keys(t)[0]&&Object.values(e)[0]===Object.values(t)[0]}function updateLinks(e,t){e.forEach(e=>{const[t]=Object.keys(e);loadLink(`${baseUrl}css/${t}/${e[t]}.css`,`${t}/${e[t]}`)});loadLink(`${baseUrl}css/${device.type}/config.css`,`${device.type}/config`);t.forEach(t=>{const[s]=Object.keys(t);const n=document.getElementById(`${s}/${t[s]}`);if(n&&!e.some(e=>areDependenciesEqual(e,t))){n.remove();loadedLinks.delete(`${baseUrl}css/${s}/${t[s]}.css`)}})}function setPresetBasedOnPreference(){const e=document.documentElement.getAttribute("preset");if(e)return;const t=window.matchMedia("(prefers-color-scheme: dark)");if(t.matches)document.documentElement.setAttribute("preset","dark");else document.documentElement.setAttribute("preset","light")}async function S4(){setPresetBasedOnPreference();window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change",setPresetBasedOnPreference);window.matchMedia("(prefers-color-scheme: light)").addEventListener("change",setPresetBasedOnPreference);document.head.appendChild(Object.assign(document.createElement("style"),{textContent:`@layer elements, presets, utilities;`}));try{await loadScript(`${baseUrl}js/device-state.min.js`);console.info(`Скрипт device-state загружен успешно | The device-state script loaded successfully`);const e=await loadDependencyMap(`${baseUrl}dependency-map.json`);if(!device)throw new Error("Объект device не определен | The device object is not defined");let t=device.type,s=device.orientation,n=e[t]?.[s]||[];loadLink(`${baseUrl}css/utilities.css`,"css/utilities");updateLinks(n,Object.values(e).flatMap(e=>Object.values(e).flat()));loadLink(`${baseUrl}css/elements.css`,"css/elements");device.onChangeOrientation(async c=>{if(s!==c){s=c;n=e[t]?.[s]||[];updateLinks(n,Object.values(e).flatMap(e=>Object.values(e).flat()))}})}catch(e){console.error("Ошибка при загрузке скрипта или инициализации устройства | Error loading script or initializing device:",e)}}